    [45.818, 5.9559],
    [47.8084, 10.5],
  ]) {
    const z = 13;
    const x = lonToTileX(lon, z);
    const y = latToTileY(lat, z);
    assert.ok(Math.abs(tileXToLon(x, z) - lon) < 1e-6, 'lon round-trip');
    assert.ok(Math.abs(tileYToLat(y, z) - lat) < 1e-6, 'lat round-trip');
    assert.ok(x > 0 && y > 0);
  }
});

