// throwaway debug: click the first result row and dump what happens
import { spawn } from 'node:child_process';
const PORT = 9333;
const chrome = spawn('chromium', ['--headless=new','--no-sandbox','--disable-gpu',`--remote-debugging-port=${PORT}`,'--user-data-dir=/tmp/dbg-chrome','about:blank'],{stdio:'ignore'});
const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
let target;
for (let i=0;i<60;i++){ try { const r=await fetch(`http://127.0.0.1:${PORT}/json/new?about:blank`,{method:'PUT'}); if(r.ok){target=(await r.json()).webSocketDebuggerUrl;break;} } catch {} await sleep(300); }
const ws=new WebSocket(target);
await new Promise(r=>ws.addEventListener('open',r,{once:true}));
let id=0; const pending=new Map(); const logs=[];
ws.addEventListener('message',(e)=>{const m=JSON.parse(e.data);
  if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(new Error(m.error.message)):p.resolve(m.result);return;}
  if(m.method==='Runtime.consoleAPICalled')logs.push(m.params.type+': '+m.params.args.map(a=>a.value??a.description).join(' '));
  if(m.method==='Runtime.exceptionThrown')logs.push('EXC: '+(m.params.exceptionDetails?.exception?.description||m.params.exceptionDetails?.text));
});
const send=(method,params={})=>new Promise((resolve,reject)=>{const i=++id;pending.set(i,{resolve,reject});ws.send(JSON.stringify({id:i,method,params}));});
const ev=async(expression)=>{const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true}); if(r.exceptionDetails) return 'EXC:'+(r.exceptionDetails.exception?.description||r.exceptionDetails.text); return r.result?.value;};
await send('Page.enable'); await send('Runtime.enable');
await send('Page.navigate',{url:'http://127.0.0.1:8787/'});
await sleep(4000);
console.log('rows:', await ev(`document.querySelectorAll('#result-list > *').length`));
console.log('row html:', String(await ev(`document.querySelector('#result-list > *')?.outerHTML`)).slice(0,900));
console.log('attribution:', JSON.stringify(await ev(`document.querySelector('#map-attribution-extra')?.textContent`)));
console.log('map-credits:', JSON.stringify(await ev(`document.querySelector('.app-map__attribution, .zh-map__credit, [class*=attrib]')?.textContent?.slice(0,200)`)));
const box = await ev(`(()=>{const n=document.querySelector('#result-list > *');n.scrollIntoView({block:'center'});const r=n.getBoundingClientRect();return {x:r.left+r.width/2,y:r.top+r.height/2,w:r.width,h:r.height};})()`);
console.log('box:', box);
const common={x:Math.round(box.x),y:Math.round(box.y),button:'left',clickCount:1};
await send('Input.dispatchMouseEvent',{type:'mousePressed',...common});
await send('Input.dispatchMouseEvent',{type:'mouseReleased',...common});
await sleep(2500);
console.log('detail hidden:', await ev(`document.querySelector('#detail')?.hidden`));
console.log('detail text:', String(await ev(`document.querySelector('#detail')?.textContent?.replace(/\\s+/g,' ').slice(0,300)`)));
console.log('url:', await ev(`location.href`));
console.log('logs:', logs.slice(0,10));
chrome.kill('SIGKILL');
process.exit(0);

